function friendlyError(error){if(error?.name==='QuotaExceededError')return'手机可用空间不足，未能保存。请先导出备份，再清理空间。';return error?.message||'这次没有完成，请再试一次。';}
function hideToast(){clearTimeout(toastTimer);toastTimer=null;toastRemaining=0;toastPointerOver=false;$('toast').hidden=true;}
function pauseToast(){if(toastTimer===null)return;clearTimeout(toastTimer);toastTimer=null;toastRemaining=Math.max(0,toastDeadline-performance.now());}
function resumeToast(){const toast=$('toast');if(toast.hidden||toastTimer!==null||toastPointerOver||toast.contains(document.activeElement))return;toastDeadline=performance.now()+toastRemaining;toastTimer=setTimeout(hideToast,toastRemaining);}
function showToast(message,undo=false){
 clearTimeout(toastTimer);toastTimer=null;
 const text=String(message??'').trim();if(!text){hideToast();return;}
 const canUndo=Boolean(undo&&lastAction);$('toast-message').textContent=text;$('undo-action').hidden=!canUndo;$('toast').hidden=false;
 // Short feedback clears promptly; longer guidance gets time to be read.
 // Deliberate hover or keyboard focus pauses dismissal without losing undo.
 toastRemaining=canUndo?5000:Math.min(5000,Math.max(2500,Array.from(text).length*80));resumeToast();
}
function showReply(text){$('conversation-reply').textContent=text;$('conversation-reply').hidden=!text;}
function updateSentenceActionNote(){if($('sentence-action-note'))$('sentence-action-note').textContent=$('sentence').value.trim()?'有未保存内容':'打字或键盘听写';}
function setSentencePanel(open){if($('sentence-panel'))$('sentence-panel').hidden=!open;$('focus-sentence')?.setAttribute('aria-expanded',String(open));updateSentenceActionNote();}
function showView(name){if(!['capture','ledger','chat','stats','settings'].includes(name))return;currentView=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!=='view-'+name);document.querySelectorAll('.bottom-nav [data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===name);if(el.dataset.view===name)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});renderAll();chatUI?.setActive(name==='chat');window.scrollTo({top:0,behavior:'instant'});}
function canUse(){if(state&&db.db)return true;showToast('本机账本尚未打开，请刷新页面重试。');return false;}
async function commit(mutator,undoAction=null){
 if(!canUse())throw new Error('账本不可写入');if(busy)throw new Error('正在保存，请稍等一下。');busy=true;
 try{const next=clone(state);mutator(next);if(next.records.length>MAX_RECORDS)throw new Error('账本已达到 50,000 笔，请先导出归档。');next.revision=state.revision+1;next.updatedAt=new Date().toISOString();await db.write(next,state.revision);state=next;if(undoAction)lastAction=undoAction;renderAll();channel?.postMessage({revision:state.revision});return next;}
 catch(error){if(error instanceof StorageConflictError){state=await db.read();lastAction=null;renderAll();}throw error;}finally{busy=false;}
}
async function ask(title,description,label='确认'){return new Promise(resolve=>{const dialog=$('confirm-dialog');$('confirm-title').textContent=title;$('confirm-description').textContent=description;$('confirm-yes').textContent=label;let settled=false;const finish=answer=>{if(settled)return;settled=true;dialog.close();$('confirm-yes').removeEventListener('click',yes);$('confirm-no').removeEventListener('click',no);dialog.removeEventListener('cancel',cancel);resolve(answer);};const yes=()=>finish(true),no=()=>finish(false),cancel=e=>{e.preventDefault();finish(false);};$('confirm-yes').addEventListener('click',yes);$('confirm-no').addEventListener('click',no);dialog.addEventListener('cancel',cancel);dialog.showModal();});}
function recordRow(record){const sign=record.type==='expense'?'−':record.type==='income'||record.type==='refund'?'+':'';const amount=record.amountCents==null?'金额待补':sign+formatMoney(record.amountCents);return`<button class="record-row" data-record="${esc(record.id)}" aria-label="查看${esc(record.merchant)}，${esc(amount)}"><span class="category-icon">${recordSticker(record)}</span><span class="record-info"><strong>${esc(record.merchant)}${record.status==='pending'?'<span class="pending-tag">待核对</span>':''}</strong><small>${esc(record.category)}${record.purpose?' · '+esc(record.purpose):''} · ${esc(record.channel)} · ${esc(typeLabels[record.type])} · ${esc(record.date?.slice(5,10)||'')}</small></span><span class="record-amount ${esc(record.status==='pending'?'pending':record.type)}">${esc(amount)}</span></button>`;}
function empty(title,description){return`<div class="empty-state">${sticker('empty','cat-empty-state')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function recentRecords(){return state.records.map((record,index)=>({record,index})).sort((a,b)=>b.record.createdAt.localeCompare(a.record.createdAt)||b.index-a.index).slice(0,4).map(item=>item.record);}
function homeRecentRecords(){return[...state.records].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,12);}
function homeDayHeading(day){
 const today=localDate(),yesterdayDate=new Date();yesterdayDate.setDate(yesterdayDate.getDate()-1);const yesterday=localDate(yesterdayDate);
 const label=day===today?'今天':day===yesterday?'昨天':dateLabel(day);
 const dayRecords=state.records.filter(record=>record.date?.slice(0,10)===day);
 const summary=summarize(dayRecords,day.slice(0,7));
 const totals=`净支出 ${formatMoney(summary.netExpenseCents)} · 收入 ${formatMoney(summary.incomeCents)}`;
 return`<div class="day-heading home-day-heading"><strong>${esc(label)}</strong><span class="home-day-totals">${esc(totals)}</span></div>`;
}
function renderHome(){
 const summary=summarize(state.records,thisMonth);$('summary-month').textContent=`${Number(thisMonth.slice(5))} 月账本`;$('home-expense').textContent=moneyPlain(summary.netExpenseCents);$('home-income').textContent=formatMoney(summary.incomeCents);$('home-refund').textContent=formatMoney(summary.refundCents);$('home-count').textContent=summary.count?`记下 ${summary.count} 笔，都是生活的小痕迹。`:'还没有记账，慢慢开始就好。';
 const records=homeRecentRecords();let lastDay='';$('recent-list').innerHTML=records.length?records.map(record=>{const day=record.date.slice(0,10),heading=day!==lastDay?homeDayHeading(day):'';lastDay=day;return heading+recordRow(record);}).join(''):empty('先记下生活里的第一笔','选一张付款截图，或说一句「午饭 28」。');
 const budget=state.budgets[thisMonth];$('home-budget').hidden=!budget;if(budget){const used=Math.max(0,summary.netExpenseCents),remaining=budget-used;$('home-budget').innerHTML=`<div class="row between"><span>${remaining>=0?'预算还剩':'已超预算'}</span><span>${esc(formatMoney(Math.abs(remaining)))}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,used/budget*100)}%"></div></div>`;}
 if($('home-budget-label'))$('home-budget-label').textContent=budget?`${budget-Math.max(0,summary.netExpenseCents)>=0?'剩余':'超出'} ${formatMoney(Math.abs(budget-Math.max(0,summary.netExpenseCents)))}`:'未设置';
 const backupAge=state.lastBackupAt?(Date.now()-Date.parse(state.lastBackupAt))/86400000:Infinity;$('backup-nudge').hidden=!state.records.length||backupAge<7;
}
function filteredRecords(){const query=$('ledger-search').value.trim().toLowerCase();const month=$('ledger-month').value;return state.records.filter(r=>(showAllMonths||r.date.startsWith(month))&&(!ledgerStatsCategory||((CATEGORIES.includes(r.category)?r.category:'其他')===ledgerStatsCategory&&r.status==='confirmed'&&['expense','refund'].includes(r.type)&&validDate(r.date)&&Number.isSafeInteger(r.amountCents)&&r.amountCents>0))&&(!query||`${r.merchant} ${r.purpose||''} ${r.notes} ${r.category}`.toLowerCase().includes(query))&&(ledgerFilter==='all'||(ledgerFilter==='pending'?r.status==='pending':r.type===ledgerFilter))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));}
function renderLedger(){
 $('pending-count').textContent=state.records.filter(r=>r.status==='pending').length;const records=filteredRecords();$('ledger-caption').textContent=`共 ${records.length} 笔${showAllMonths?' · 全部月份':''}`;if($('ledger-category-filter')){$('ledger-category-filter').hidden=!ledgerStatsCategory;$('ledger-category-filter').textContent=ledgerStatsCategory?`${ledgerStatsCategory} · 已确认支出与退款 ×`:'';}if(!records.length){$('ledger-list').innerHTML=empty(ledgerStatsCategory?'这个分类下没有匹配的记录':'这里还没有流水',ledgerStatsCategory?'可以清除分类筛选，或修改搜索文字。':'记一笔，或调整月份、搜索和筛选条件。');$('load-more').hidden=true;return;}
 let lastDay='';$('ledger-list').innerHTML=records.slice(0,ledgerLimit).map(record=>{const day=record.date.slice(0,10);let heading='';if(day!==lastDay){lastDay=day;heading=`<div class="day-heading">${esc(dateLabel(day))}</div>`;}return heading+recordRow(record);}).join('');$('load-more').hidden=records.length<=ledgerLimit;
}
function setLedgerTypeFilter(value){ledgerFilter=value;document.querySelectorAll('[data-filter]').forEach(button=>{const active=button.dataset.filter===value;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
function openStatsCategory(category){
 if(!CATEGORIES.includes(category))return;
 ledgerStatsCategory=category;ledgerLimit=100;showAllMonths=false;setLedgerTypeFilter('all');
 $('ledger-search').value='';$('ledger-month').value=$('stats-month').value||thisMonth;$('all-months').setAttribute('aria-pressed','false');
 showView('ledger');$('ledger-title').setAttribute('tabindex','-1');$('ledger-title').focus({preventScroll:true});
}
function renderStats(){
 const month=$('stats-month').value||thisMonth;const summary=summarize(state.records,month);$('stats-expense').textContent=formatMoney(summary.netExpenseCents);$('stats-income').textContent=formatMoney(summary.incomeCents);$('stats-gross').textContent=`${formatMoney(summary.expenseCents)} / ${formatMoney(summary.refundCents)}`;$('stats-count').textContent=summary.count;
 const items=Object.entries(summary.byCategory).filter(([,amount])=>amount!==0).sort((a,b)=>b[1]-a[1]);const max=Math.max(...items.map(([,amount])=>Math.abs(amount)),1);$('category-chart').innerHTML=items.length?items.map(([category,amount])=>`<button type="button" class="category-bar category-drilldown" data-stats-category="${esc(category)}" aria-label="查看${esc(month)}的${esc(category)}已确认支出与退款，净额${esc(formatMoney(amount))}"><span class="category-rank-icon">${categoryIcon(category)}</span><span class="category-rank-info"><span class="row between"><span>${esc(category)}</span><strong class="${amount<0?'negative':''}">${esc(formatMoney(amount))}${amount<0?' · 净退款':''}</strong></span><span class="bar-track"><span class="bar-fill" style="width:${Math.abs(amount)/max*100}%"></span></span></span><span class="category-rank-chevron">${icon('chevron-right')}</span></button>`).join(''):empty('这个月还没有分类支出','待核对和内部转账不计入收支金额。');
 const budget=state.budgets[month];if(!budget){$('budget-display').innerHTML=empty('暂时不设，也没关系','想控制开销时，给这个月设个总预算。');return;}
 const used=Math.max(0,summary.netExpenseCents),remaining=budget-used,over=remaining<0;$('budget-display').innerHTML=`<div class="budget-number">${esc(formatMoney(Math.abs(remaining)))}</div><div class="budget-label">${over?'本月超出预算':'本月剩余额度'} · 总预算 ${esc(formatMoney(budget))}</div><div class="budget-track ${over?'over':''}"><div style="width:${Math.min(100,used/budget*100)}%"></div></div><p class="budget-status ${over?'over':''}">已使用 ${(used/budget*100).toFixed(0)}%${over?'，后面的支出留意一点就好。':'，按自己的节奏来。'}</p>`;
}
function renderSettings(){
 $('backup-status').textContent=state.lastBackupAt?`上次发起备份：${new Date(state.lastBackupAt).toLocaleString('zh-CN')}（请确认文件已保存）`:'还没有导出过备份';
 const rules=Object.entries(state.rules);$('rules-list').innerHTML=rules.length?rules.map(([merchant,category])=>`<div class="rule-row"><span>${esc(merchant)}</span><span class="subtle-tag">${esc(category)}</span><button class="text-button" data-remove-rule="${esc(merchant)}" aria-label="忘记${esc(merchant)}的分类">忘记</button></div>`).join(''):'<p class="micro-copy">还没有记住的商户，核对记账时可以随手添加。</p>';
 const standalone=Boolean(navigator.standalone||matchMedia('(display-mode: standalone)').matches);$('bridge-context').textContent=`当前账本尾号 ${state.ledgerId.slice(-6)} · ${standalone?'独立主屏 App。请用 Safari 普通网页重新打开并绑定截图入口。':'当前浏览器。请先确认这是你日常使用的 Safari 账本。'}`;$('copy-bridge').disabled=standalone;
}
function renderAll(){if(!state)return;renderHome();renderLedger();renderStats();renderSettings();chatUI?.syncSavedRecords();}

function enrichDraft(input,context=null){const draft=normalizeRecord(input);const goods=draft.notes.match(/商品：([^；]+)/)?.[1]||'';const suggestion=context&&typeof context==='object'&&context.category?context:inferReceiptContext(draft,{rules:state.rules,goods});if(draft.category==='其他'&&suggestion.category!=='其他')draft.category=suggestion.category;if(!draft.purpose&&suggestion.purpose){draft.purpose=suggestion.purpose;if(suggestion.timeBasis){if(draft.source==='ocr')draft.status='pending';draft.notes=safeText([draft.notes,'用途按付款时间建议，可修改'].filter(Boolean).join('；'));}}return draft;}
function renderRecognitionSuggestion(){if(!review)return;const draft=collectReview();if($('review-sticker'))$('review-sticker').innerHTML=recordSticker(draft,'cat-review');const suggestion=!review.categoryDirty&&!review.contextChanged&&review.receipt?.suggestions?.[review.index]||inferReceiptContext({...draft,purpose:''},{rules:state.rules,goods:review.receipt?.suggestions?.[review.index]?.goods||''});const visible=draft.category!=='其他'&&(draft.source!=='manual'||$('review-merchant').value.trim());$('recognition-summary').hidden=!visible;$('recognition-category').textContent=draft.category;$('recognition-purpose').textContent=draft.purpose||'用途可补充';const basis=Array.isArray(suggestion.basis)?suggestion.basis:[suggestion.basis].filter(Boolean);$('recognition-basis').textContent=review.purposeDirty?'分类和用途以你当前填写的内容为准。':basis.join('；');}
function updateReviewSuggestions(event){if(!review)return;const id=event.target.id,goods=review.receipt?.suggestions?.[review.index]?.goods||'';if(id==='review-type'&&$('review-money-label'))$('review-money-label').textContent=`${typeLabels[$('review-type').value]||'待核对'}金额`;if(['review-merchant','review-date','review-type'].includes(id))review.contextChanged=true;if(id==='review-category')review.categoryDirty=true;if(id==='review-purpose')review.purposeDirty=true;if(id==='review-merchant'&&!review.categoryDirty)$('review-category').value=classify($('review-merchant').value,goods,state.rules);if(!review.purposeDirty){const draft=collectReview();const suggestion=inferReceiptContext({...draft,purpose:''},{rules:state.rules,goods});$('review-purpose').value=suggestion.purpose||'';}renderRecognitionSuggestion();updateDuplicateNotice();}
function collectReview(){if(!review)return null;const draft=review.drafts[review.index];let date=$('review-date').value;if(date===draft.date?.slice(0,10)&&draft.date.length>10)date=draft.date;return normalizeRecord({...draft,amountCents:parseMoney($('review-amount').value),type:$('review-type').value,category:$('review-category').value,merchant:$('review-merchant').value.trim(),purpose:$('review-purpose').value.trim(),date,channel:$('review-channel').value,notes:$('review-notes').value,status:'confirmed'});}
function rememberCurrentDraft(){if(!review)return;review.dirtys[review.index]={category:review.categoryDirty,purpose:review.purposeDirty,context:review.contextChanged};const draft=collectReview();review.drafts[review.index]={...draft,status:review.drafts[review.index].status};review.remembers[review.index]=$('remember-category').checked;}
function reviewAIContext(){if(!review?.receipt)return null;return{text:$('review-ocr-text').value,candidates:review.receipt.suggestions?.[review.index]?.merchantCandidates||[],draft:collectReview(),imageFile:review.receipt.imageFile};}
function renderMerchantCandidates(){const suggestion=review?.receipt?.suggestions?.[review.index];const candidates=Array.isArray(suggestion?.merchantCandidates)?suggestion.merchantCandidates.filter(name=>typeof name==='string'&&name.trim()):[];$('merchant-candidates').hidden=!candidates.length||!suggestion.merchantNeedsReview;$('merchant-candidate-buttons').replaceChildren();$('merchant-candidate-caption').textContent=candidates.length>1?'本机读到的店名有不同写法，已保留主要读法。请对照截图，点选或直接修改：':'已读到这个商户候选，请对照截图确认，也可以直接修改：';for(const name of candidates){const button=document.createElement('button');button.type='button';button.className='merchant-candidate';button.textContent=name;button.setAttribute('aria-pressed',String($('review-merchant').value===name));button.addEventListener('click',()=>{$('review-merchant').value=name;$('review-merchant').dispatchEvent(new Event('input',{bubbles:true}));for(const item of $('merchant-candidate-buttons').children)item.setAttribute('aria-pressed',String(item===button));});$('merchant-candidate-buttons').append(button);}}
function updateDuplicateNotice(){if(!review||!state)return;const draft=collectReview();const dup=findDuplicate(draft,state.records.filter(r=>r.id!==review.existingId));$('duplicate-notice').hidden=dup.level==='none';if(dup.level!=='none')$('duplicate-notice').textContent=(dup.level==='exact'?'账本已有相同账单。':'这笔可能记过：')+dup.reason+'。保存前会再请你确认。';}
function drawReview(){
 review.categoryDirty=review.dirtys?.[review.index]?.category??Boolean(review.existingId);review.purposeDirty=review.dirtys?.[review.index]?.purpose??Boolean(review.existingId);review.contextChanged=review.dirtys?.[review.index]?.context??Boolean(review.existingId);const draft=review.drafts[review.index];const missing=[];if(draft.amountCents==null)missing.push('金额');if(!draft.merchant||draft.merchant==='未识别商户')missing.push('商户 / 对方');$('review-title').textContent=review.existingId?'修改这笔记录':review.drafts.length>1?`核对第 ${review.index+1} / ${review.drafts.length} 笔`:'核对这一笔';$('review-eyebrow').textContent=review.existingId?'改好后保存，就这么简单':draft.source==='ocr'&&missing.length?'有信息没读全，补一下再记':'提取好了，最后看一眼';$('review-amount').value=draft.amountCents==null?'':(draft.amountCents/100).toFixed(2);$('review-purpose').value=draft.purpose||'';$('review-type').value=draft.type;$('review-category').value=draft.category;$('review-merchant').value=draft.merchant==='未识别商户'?'':draft.merchant;$('review-date').value=draft.date?.slice(0,10)||localDate();$('review-channel').value=draft.channel;$('review-notes').value=draft.notes||'';$('remember-category').checked=review.remembers[review.index]||false;
 if($('review-money-label'))$('review-money-label').textContent=`${typeLabels[draft.type]||'待核对'}金额`;
 $('review-missing').hidden=draft.source!=='ocr'||!missing.length;$('review-missing').textContent=missing.length?`没有读到：${missing.join('、')}。请对照截图补全；也可以展开下方“查看识别文字”，修正后重新提取。`:'';
 if($('review-more'))$('review-more').open=draft.type!=='expense'||!validDate(draft.date)||(draft.status==='pending'&&/日期|年份|时间不明|无效时间|退款|转账|收支|渠道|币种|外币/.test(draft.notes||''));
 $('review-notice').hidden=draft.status!=='pending';$('review-notice').textContent=draft.status==='pending'?(draft.notes||'这笔信息不完整，请核对金额、日期和收支类型。'):'';$('review-errors').hidden=true;$('delete-record').hidden=!review.existingId;$('save-record').textContent=review.existingId?'保存修改':review.drafts.length>1?'记下这一笔':'确认记下';$('draft-tabs').hidden=review.drafts.length<2;$('draft-tabs').innerHTML=review.drafts.map((r,i)=>`<button type="button" class="${i===review.index?'active':''}" data-draft-index="${i}">${i+1}. ${esc(r.merchant)} · ${esc(formatMoney(r.amountCents))}</button>`).join('');renderRecognitionSuggestion();renderMerchantCandidates();updateDuplicateNotice();aiAssistant?.refreshReview();
}
function clearOCRText(){aiAssistant?.clearReview();$('merchant-candidates').hidden=true;$('merchant-candidate-buttons').replaceChildren();$('review-ocr-text').value='';$('review-ocr-extra-text').textContent='';$('review-ocr-extra').hidden=true;$('review-ocr-details').open=false;$('review-ocr-details').hidden=true;$('review-ocr-message').textContent='';}
function openReview(drafts,existingId=null,receipt=null){if(!canUse())return;clearOCRText();review={drafts:drafts.map((r,i)=>existingId?normalizeRecord(r):enrichDraft(r,receipt?.suggestions?.[i])),index:0,existingId,receipt,categoryDirty:Boolean(existingId),purposeDirty:Boolean(existingId),dirtys:{},originalStamp:existingId?state.records.find(r=>r.id===existingId)?.updatedAt:null,remembers:{}};if(receipt){$('review-ocr-details').hidden=false;$('review-ocr-text').value=receipt.text.slice(0,20000);$('review-ocr-extra').hidden=!receipt.supplement;$('review-ocr-extra-text').textContent=(receipt.supplement||'').slice(0,20000);}drawReview();$('review-title').setAttribute('tabindex','-1');$('review-dialog').showModal();setTimeout(()=>{if(review&&$('review-dialog').open)(review.drafts[0].amountCents==null?$('review-amount'):$('review-title')).focus({preventScroll:true});},30);}
function reparseOCRText(){if(!review?.receipt)return;const text=$('review-ocr-text').value;const parsed=parseReceipt(text,{rules:state.rules});if(!parsed.drafts.length){$('review-ocr-message').textContent=parsed.reason||'还没有找到交易信息，请直接补全上面的金额和商户。';return;}review.receipt.suggestions=parsed.suggestions||[];review.drafts=parsed.drafts.map((r,i)=>enrichDraft(r,parsed.suggestions?.[i]));review.index=0;review.remembers={};review.categoryDirty=false;review.purposeDirty=false;review.dirtys={};drawReview();$('review-ocr-message').textContent='已按上方文字重新提取。请核对金额、商户和日期，再确认记下。';}
function closeReview(){if($('review-dialog').open)$('review-dialog').close();review=null;}
function recordErrors(draft){const errors=validateRecord(draft);if(!validDate(draft.date))errors.push('日期需要在 1900 至 2200 年之间。');if(draft.amountCents>MAX_CENTS)errors.push('单笔金额超过首版上限 999,999,999.99 元。');return[...new Set(errors)];}
function configureChatService(){showView('settings');$('ai-settings-disclosure').open=true;$('return-chat').hidden=false;$('ai-base-url').focus({preventScroll:true});$('ai-settings-disclosure').scrollIntoView({block:'start',behavior:'instant'});}
function editChatDraft(draft){
 if(!canUse()||!draft)return;
 const saved=state.records.find(record=>record.id===draft.id);
 if(saved){openReview([saved],saved.id);return;}
 if(draft.currency==='OTHER'||draft.paymentState==='not_completed'){showToast('这笔不是可记下的人民币已发生交易，请先检查原图。');return;}
 const notes=[draft.notes,'AI 整理，请对照原文核对',!draft.date?'没有读到日期，请填写实际日期':'',draft.currency&&draft.currency!=='CNY'?'币种未确定，请确认人民币金额':'',draft.paymentState==='uncertain'?'支付状态未确定，请对照原图核对':''].filter(Boolean).join('；');
 openReview([normalizeRecord({...draft,source:'manual',notes:safeText(notes),status:'pending'})]);
 if(!draft.date){review.drafts[0].date='';$('review-date').value='';}
 if(draft.needsAttention||!draft.date)$('review-more').open=true;
}
async function saveChatDraft(input,{automatic=false,signal}={}){
 const stopped=()=>{if(signal?.aborted){const error=new Error('本次处理已停止。');error.name='AbortError';throw error;}};stopped();
 if(!canUse())throw new Error('本机账本尚未打开。');
 if(chatSaveBusy||busy)throw new Error('正在保存另一笔，请稍等一下。');
 if(!input||typeof input!=='object'||!input.id)throw new Error('这张卡片无效，请重新整理。');
 const existing=state.records.find(record=>record.id===input.id);if(existing)return clone(existing);
 if(input.needsAttention||input.currency!=='CNY'||!['stated','completed'].includes(input.paymentState)||!validDate(input.date)||input.date.slice(0,10)>localDate()||!String(input.merchant||'').trim())throw new Error('这笔还有信息需要核对，请点“补全并核对”。');
 if(automatic&&input.type==='transfer'){const error=new Error('转账需要核对。');error.code='REVIEW_REQUIRED';throw error;}
 const draft=normalizeRecord({...input,source:'manual',notes:safeText([input.notes,'AI 对话整理'].filter(Boolean).join('；')),status:'confirmed'}),errors=recordErrors(draft);if(errors.length)throw new Error(errors.join('；'));
 chatSaveBusy=true;
 try{
  const revision=state.revision,duplicate=findDuplicate(draft,state.records);
  if(duplicate.level!=='none'){
   if(automatic){const error=new Error('这笔可能已经记过，请核对后再保存。');error.code='DUPLICATE';throw error;}
   if(!await ask('这笔可能已经记过',`${duplicate.reason}。已有：${duplicate.record.merchant}，${formatMoney(duplicate.record.amountCents)}，${dateLabel(duplicate.record.date)}。请确认它们是两笔独立交易。`,'仍然记下'))return null;
   if(state.revision!==revision)throw new Error('账本刚有变化，请再核对一次这张卡片。');
  }
  stopped();await commit(next=>{stopped();if(next.records.some(record=>record.id===draft.id))throw new Error('这张卡片已经记下。');next.records.push(draft);},{kind:'add',ids:[draft.id],before:null,description:'刚记下的 AI 账单'});
  if(currentView!=='chat')showToast('已记下，账目留在本机',true);return clone(draft);
 }finally{chatSaveBusy=false;}
}
async function saveReviewed(event){
 event.preventDefault();if(!review||!canUse())return;if(aiAssistant?.isBusy()){showToast('AI 仍在等待，请先取消等待或等结果返回，再保存。');return;}const draft=collectReview();const errors=recordErrors(draft);if(!$('review-merchant').value.trim())errors.push('请填写商家或用途，例如：午饭。');if(errors.length){if($('review-more')&&/日期|年份|时间|收支|类型|渠道|备注/.test(errors.join('；')))$('review-more').open=true;$('review-errors').textContent=errors.join('；');$('review-errors').hidden=false;return;}
 const duplicate=findDuplicate(draft,state.records.filter(r=>r.id!==review.existingId));if(duplicate.level!=='none'&&!await ask('这笔可能已经记过',`${duplicate.reason}。已有：${duplicate.record.merchant}，${formatMoney(duplicate.record.amountCents)}，${dateLabel(duplicate.record.date)}。确认要再记一笔吗？`,'仍然保存'))return;
 const existingId=review.existingId;const before=existingId?state.records.find(r=>r.id===existingId):null;if(existingId&&(!before||before.updatedAt!==review.originalStamp)){showToast('这笔记录已在其他页面修改，请关闭核对页后重新打开。');return;}if(!existingId)draft.createdAt=new Date().toISOString();
 const remembered=$('remember-category').checked;const ruleName=draft.merchant.trim();const oldRule=Object.hasOwn(state.rules,ruleName)?state.rules[ruleName]:null;
 $('save-record').disabled=true;
 try{await commit(next=>{if(existingId){const i=next.records.findIndex(r=>r.id===existingId);if(i<0)throw new Error('找不到原记录，请重新打开流水。');next.records[i]=draft;}else next.records.push(draft);if(remembered&&ruleName&&!['__proto__','constructor','prototype','未识别商户'].includes(ruleName))next.rules[ruleName]=draft.category;},{kind:existingId?'edit':'add',ids:[draft.id],before:before?clone(before):null,ruleName:remembered?ruleName:null,oldRule,description:existingId?'本次修改':'刚记下的一笔'});
  if(review.sentenceText!==undefined&&$('sentence').value.trim()===review.sentenceText){$('sentence').value='';updateSentenceActionNote();showReply('');}if(review.drafts.length>1){review.drafts.splice(review.index,1);review.index=Math.min(review.index,review.drafts.length-1);review.remembers={};review.dirtys={};drawReview();showToast('已记下，继续核对下一笔',true);}else{if(!$('sentence').value.trim())setSentencePanel(false);closeReview();showToast(existingId?'修改已保存':'记下了，这笔留在本机账本',true);}
 }catch(error){$('review-errors').textContent=friendlyError(error);$('review-errors').hidden=false;}finally{$('save-record').disabled=false;}
}

async function undoLast(){if(!lastAction){showToast('当前没有可以撤销的操作。');return;}const action=lastAction,revision=state.revision;if(!await ask('撤销'+action.description,action.kind==='import'?`将移除刚导入的 ${action.ids.length} 笔记录。`:'账本会恢复到这次操作之前的状态。','确认撤销'))return;if(state.revision!==revision||lastAction!==action){showToast('账本在确认期间有变化，本次撤销已取消，请重新查看。');return;}try{await commit(next=>{if(action.kind==='add'||action.kind==='import'){const ids=new Set(action.ids);next.records=next.records.filter(r=>!ids.has(r.id));}else if(action.kind==='edit'){const i=next.records.findIndex(r=>r.id===action.before.id);if(i>=0)next.records[i]=action.before;else next.records.push(action.before);}else if(action.kind==='delete')next.records.push(action.before);if(action.ruleName){if(action.oldRule===null)delete next.rules[action.ruleName];else next.rules[action.ruleName]=action.oldRule;}});lastAction=null;$('undo-action').hidden=true;if(currentView!=='chat')showToast('已撤销');}catch(error){showToast(friendlyError(error));}}
async function parseSentence(){
 if(!canUse())return;const text=$('sentence').value.trim();const result=parseText(text,{rules:state.rules});if(result.intent==='create'){showReply(result.reply||'');openReview(result.drafts);if(review)review.sentenceText=text;}
 else if(result.intent==='edit'){const last=recentRecords()[0];if(!last){showReply('账本还是空的，先记下第一笔吧。');return;}openReview([{...last,...result.patch}],last.id);if(review)review.sentenceText=text;}
 else if(result.intent==='undo')await undoLast();
 else if(result.intent==='query'){const month=result.query?.month;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month||'')){showReply('月份没看明白，可以说“本月花了多少”或“2026年10月餐饮花了多少”。');return;}const summary=summarize(state.records,month);const category=result.query?.category;const amount=category?summary.byCategory[category]:/收入/.test(text)?summary.incomeCents:summary.netExpenseCents;showReply(`${month.replace('-',' 年 ')} 月${category||(/收入/.test(text)?'收入':'净支出')}：${formatMoney(amount)}。只统计已确认记录。`);$('stats-month').value=month;}
 else showReply(result.reply||'试试“午饭 28，地铁 6”，识别后再确认。');
}

async function readScreenshot(file){if(!file||!canUse())return;if(ocrAbort){showToast('先等这一张识别完成，或点取消。');return;}ocrAbort=new AbortController();$('ocr-progress').hidden=false;$('ocr-meter').value=0;$('ocr-progress-detail').textContent='图片留在当前设备，不上传。首次识别需要载入识别包。';showReply('');
 try{const result=await recognizeScreenshot(file,{signal:ocrAbort.signal,onProgress:progress=>{const value=typeof progress==='number'?progress:(progress.progress??0);$('ocr-meter').value=Math.max(0,Math.min(1,value));$('ocr-progress-title').textContent=`正在本机识别 ${Math.round(value*100)}%`;if(progress.status)$('ocr-progress-detail').textContent=progress.status;}});const parsed=parseReceiptReadings(result.readings||[result],{rules:state.rules});if(!parsed.drafts.length){showReply(parsed.reason||'没有找到清晰的账单信息，请选单笔付款成功截图。');return;}if(result.confidence!=null&&result.confidence<60){parsed.drafts.forEach(r=>{r.status='pending';r.notes=[r.notes,'图片识别不够清晰，请仔细核对金额和商户'].filter(Boolean).join('；');});}openReview(parsed.drafts,null,{imageFile:file,text:result.text,suggestions:parsed.suggestions||[],supplement:result.readings?.slice(1).map(r=>r.text).join('\n\n')||''});}
 catch(error){if(error.name==='AbortError')showToast('已取消识别');else showReply(friendlyError(error));}
 finally{ocrAbort=null;$('ocr-progress').hidden=true;await disposeOCR();refreshOfflineStatus();}
}

function duplicateIndex(records){const ids=new Map(),source=new Map(),similar=new Map();for(const r of records){ids.set(r.id,r);if(r.sourceId){const k=[r.channel,r.type,r.sourceId].join('|');if(!source.has(k))source.set(k,[]);source.get(k).push(r);}const k=[r.date?.slice(0,10),r.type,r.amountCents,r.merchant?.normalize('NFKC').trim().toLowerCase()].join('|');if(!similar.has(k))similar.set(k,[]);similar.get(k).push(r);}return{lookup:r=>{const k=[r.date?.slice(0,10),r.type,r.amountCents,r.merchant?.normalize('NFKC').trim().toLowerCase()].join('|');return findDuplicate(r,[...(ids.has(r.id)?[ids.get(r.id)]:[]),...(source.get([r.channel,r.type,r.sourceId].join('|'))||[]),...(similar.get(k)||[])]);},add:r=>{ids.set(r.id,r);if(r.sourceId){const k=[r.channel,r.type,r.sourceId].join('|');if(!source.has(k))source.set(k,[]);source.get(k).push(r);}const k=[r.date?.slice(0,10),r.type,r.amountCents,r.merchant?.normalize('NFKC').trim().toLowerCase()].join('|');if(!similar.has(k))similar.set(k,[]);similar.get(k).push(r);}};}
async function readImport(file){
 if(!file||!canUse())return;$('pick-import').disabled=true;$('pick-import').querySelector('strong').textContent='正在读取…';
 try{const parsed=await readBillFile(file,{rules:state.rules});const skipped=[...(parsed.skipped||[])];const entries=[];const index=duplicateIndex(state.records);for(const [i,item]of parsed.drafts.entries()){const draft=enrichDraft(item);const errors=recordErrors(draft);if(errors.length){skipped.push({row:i+1,reason:errors.join('；')});continue;}const duplicate=index.lookup(draft);if(duplicate.level==='possible'){draft.status='pending';draft.notes=safeText([draft.notes,'可能重复，请核对后确认'].filter(Boolean).join('；'));}entries.push({draft,duplicate,selected:duplicate.level!=='exact'});index.add(draft);}
 importBatch={entries,skipped,warnings:parsed.warnings||[],format:parsed.format,limit:200,filename:safeText(file.name,100)};drawImport();$('import-dialog').showModal();
 }catch(error){showReply(friendlyError(error));showToast('账单未导入');}finally{$('pick-import').disabled=false;$('pick-import').querySelector('strong').textContent='导入账单';}
}
function importSummary(){if(!importBatch)return;const selected=importBatch.entries.filter(x=>x.selected),pending=selected.filter(x=>x.draft.status==='pending').length;const label=({wechat:'微信',alipay:'支付宝',generic:'通用'})[importBatch.format]||'通用';$('import-summary').textContent=`${label}账单 · ${importBatch.filename}：可读取 ${importBatch.entries.length} 笔，已选 ${selected.length} 笔${pending?`（${pending} 笔待核对）`:''}。`;$('commit-import').textContent=`导入所选 ${selected.length} 笔`;$('commit-import').disabled=!selected.length;const all=$('import-select-all');if(all){all.checked=!!selected.length&&selected.length===importBatch.entries.length;all.indeterminate=selected.length>0&&selected.length<importBatch.entries.length;}}
function drawImport(){
 const batch=importBatch;$('import-error').hidden=true;$('import-warnings').hidden=!batch.warnings.length;$('import-warnings').textContent=batch.warnings.join('；');$('import-skips').hidden=!batch.skipped.length;$('import-skips').querySelector('summary').textContent=`查看未导入的 ${batch.skipped.length} 行`;$('import-skips-list').innerHTML=batch.skipped.slice(0,300).map(item=>`<p>第 ${esc(item.row)} 行：${esc(item.reason)}</p>`).join('')+(batch.skipped.length>300?'<p>更多行因同类问题已跳过，请核对原账单。</p>':'');
 $('import-table-wrap').innerHTML=batch.entries.length?`<table><thead><tr><th><input type="checkbox" id="import-select-all" aria-label="全选所有记录，包括重复项"></th><th>日期 / 商家</th><th>分类</th><th>金额</th><th>状态</th></tr></thead><tbody>${batch.entries.slice(0,batch.limit).map((entry,i)=>`<tr class="${entry.selected?'':'unselected'}"><td><input type="checkbox" data-import-index="${i}" aria-label="选择第${i+1}笔" ${entry.selected?'checked':''}></td><td>${esc(entry.draft.date.slice(0,10))}<br>${esc(entry.draft.merchant)}</td><td>${esc(entry.draft.category)}${entry.draft.purpose?`<br><small>${esc(entry.draft.purpose)} · 用途建议</small>`:''}</td><td>${esc(formatMoney(entry.draft.amountCents))}<small>${esc(typeLabels[entry.draft.type])}</small></td><td>${entry.duplicate.level==='exact'?'相同账单':entry.duplicate.level==='possible'?'可能重复':entry.draft.status==='pending'?'待核对':'可入账'}</td></tr>`).join('')}</tbody></table>${batch.entries.length>batch.limit?`<button class="text-button import-more" id="import-show-more">已显示 ${batch.limit} 笔，继续显示 200 笔</button>`:''}`:empty('这份文件没有可导入的交易','可查看上面的提示，或选择原始导出的账单重试。');importSummary();
}
async function commitImport(){
 if(!importBatch||!canUse())return;const selected=importBatch.entries.filter(x=>x.selected);if(!selected.length)return;const current=duplicateIndex(state.records);let exact=0;for(const entry of selected){if(current.lookup(entry.draft).level==='exact')exact++;current.add(entry.draft);}if(exact&&!await ask('所选内容中有重复账单',`有 ${exact} 笔与现有账本或同批记录相同。确认这些是独立交易后，才保留它们。`,'仍导入所选'))return;
 $('commit-import').disabled=true;try{const records=selected.map(x=>x.draft);await commit(next=>{next.records.push(...records);},{kind:'import',ids:records.map(r=>r.id),description:`刚才导入的 ${records.length} 笔`});$('import-dialog').close();importBatch=null;ledgerStatsCategory='';showView('ledger');showAllMonths=true;$('all-months').setAttribute('aria-pressed','true');renderLedger();showToast(`已导入 ${records.length} 笔${records.some(r=>r.status==='pending')?'，待核对记录暂不计入统计':''}`,true);}catch(error){$('import-error').textContent=friendlyError(error);$('import-error').hidden=false;}finally{$('commit-import').disabled=false;}
}

async function downloadFile(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),120000);}
async function backup(){if(!canUse())return;try{await downloadFile(`轻记完整备份-${localDate()}.json`,JSON.stringify(makeBackup(state),null,2),'application/json;charset=utf-8');await commit(next=>{next.lastBackupAt=new Date().toISOString();});showToast('已发起备份下载，请确认保存到“文件”中。');}catch(error){showToast(friendlyError(error));}}
async function restore(file){
 if(!file||!canUse())return;try{if(file.size>25*1024*1024)throw new Error('备份文件超过 25MB，请拆分后再恢复。');const parsed=parseBackup(await file.text());const ids=new Set(state.records.map(r=>r.id));const additions=parsed.records.filter(r=>!ids.has(r.id));const existing=parsed.records.length-additions.length;if(!await ask('从这份备份恢复',`将加入 ${additions.length} 笔记录，合并分类习惯和预算。${existing?`${existing} 笔已有相同标识，保留本机版本。`:''}当前已有记录会保留。`,'确认合并恢复'))return;let added=0;await commit(next=>{const currentIds=new Set(next.records.map(r=>r.id));const fresh=parsed.records.filter(r=>!currentIds.has(r.id));added=fresh.length;next.records.push(...fresh);next.rules={...parsed.rules,...next.rules};next.budgets={...parsed.budgets,...next.budgets};});lastAction=null;showToast(`恢复完成，新增 ${added} 笔。`);}
 catch(error){showToast(friendlyError(error));}
}
async function refreshOfflineStatus(){
 const controller=!!navigator.serviceWorker?.controller;const resources=await isOCRReady().catch(()=>false);$('ocr-status').textContent=resources?(controller?'已准备，可离线':'已下载，页面离线功能待就绪'):'未准备 · 约 37MB';$('ocr-status').classList.toggle('ready',resources&&controller);
 let shellReady=false;if('caches'in window&&controller){const names=await caches.keys();for(const name of names.filter(n=>n.startsWith('qingji-shell-'))){const cache=await caches.open(name);const required=['./index.html','./app.js','./lib/core.js','./lib/importer.js','./bill-worker.js','./vendor/xlsx.full.min.js'];const matches=await Promise.all(required.map(url=>cache.match(new URL(url,location.href))));if(matches.every(Boolean))shellReady=true;}}
 $('shell-status').textContent=shellReady?'已准备，可离线':'未完成缓存，请联网刷新';$('shell-status').classList.toggle('ready',shellReady);$('prepare-offline').textContent=resources?'检查并补齐识别包':'准备离线识别包 · 约 37MB';
 if(navigator.storage?.estimate){const estimate=await navigator.storage.estimate().catch(()=>null);if(estimate)$('storage-status').textContent=`当前网站约占用 ${((estimate.usage||0)/1024/1024).toFixed(1)} MB。浏览器可能清理数据，备份最可靠。`;}
}
async function prepareOffline(){if(offlineAbort)return;offlineAbort=new AbortController();$('prepare-offline').disabled=true;$('offline-meter').hidden=false;try{await prepareOCR({signal:offlineAbort.signal,onProgress:progress=>{const value=typeof progress==='number'?progress:(progress.progress??0);$('offline-meter').value=value;$('ocr-status').textContent=`准备中 ${Math.round(value*100)}%`;}});await refreshOfflineStatus();showToast(navigator.serviceWorker?.controller?'识别包已准备。建议先用飞行模式试记一笔。':'识别包已下载，请联网刷新让离线页面生效。');}catch(error){showToast(friendlyError(error));await refreshOfflineStatus();}finally{offlineAbort=null;$('prepare-offline').disabled=false;$('offline-meter').hidden=true;}}
function showUpdateStatus(message,recovery=false){$('update-status').hidden=false;$('update-status-message').textContent=message;$('update-recovery').hidden=!recovery;}
function setUpdateWorker(worker){waitingWorker=worker||null;$('update-notice').hidden=!worker;if(!updateBusy)$('check-update').textContent=worker?'更新轻记':'检查更新';}
function unfinishedWork(){return Boolean(busy||ocrAbort||offlineAbort||review||importBatch||aiAssistant?.hasUnsavedWork()||chatUI?.hasUnsavedWork()||document.querySelector('dialog[open]')||$('sentence').value.trim());}
function setUpdateBusy(value){updateBusy=value;$('check-update').disabled=value;$('apply-update').disabled=value;$('check-update').textContent=value?'正在检查…':waitingWorker?'更新轻记':'检查更新';}
async function activateAndReload(target){if(unfinishedWork()){const message='请先保存或取消当前草稿，再更新。';showUpdateStatus(message);showToast(message);return false;}showUpdateStatus('正在载入新版，已保存的账目会保留。');await activateUpdate(target,{onStatus:showUpdateStatus});location.reload();return true;}
async function applyProgramUpdate(){if(updateBusy)return;setUpdateBusy(true);try{if(!appRegistration&&!waitingWorker){showUpdateStatus('请先点“检查更新”。');return;}await activateAndReload(appRegistration||waitingWorker);}catch(error){showUpdateStatus(friendlyError(error),true);}finally{setUpdateBusy(false);}}
async function checkAppUpdate(){if(updateBusy)return;const wasReady=Boolean(waitingWorker);setUpdateBusy(true);try{const result=await checkForUpdate({onStatus:showUpdateStatus});appRegistration=result.registration;if(result.worker){setUpdateWorker(result.worker);if(wasReady)await activateAndReload(result.registration);else showUpdateStatus('新版已准备好，保存草稿后点“更新轻记”。');}else{const version=await getWorkerVersion(result.registration.active);if(version&&version!==APP_CACHE){setUpdateWorker(result.registration.active);if(wasReady)await activateAndReload(result.registration);else showUpdateStatus('新版已安装，保存草稿后点“更新轻记”重新打开。');}else{setUpdateWorker(null);showUpdateStatus(version?'已是最新版本 · '+APP_VERSION_LABEL:'暂未确认当前版本，请使用更新入口。',!version);}}}catch(error){showUpdateStatus(friendlyError(error),true);}finally{setUpdateBusy(false);}}
async function setupServiceWorker(){
 if(!('serviceWorker'in navigator)||!window.isSecureContext){$('shell-status').textContent='需要 HTTPS 才能准备离线页面';return;}
 try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});appRegistration=registration;const observe=worker=>{if(!worker)return;const inspect=()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)setUpdateWorker(registration.waiting||worker);};worker.addEventListener('statechange',inspect);inspect();};if(registration.waiting)setUpdateWorker(registration.waiting);observe(registration.installing);registration.addEventListener('updatefound',()=>observe(registration.installing));navigator.serviceWorker.addEventListener('controllerchange',()=>refreshOfflineStatus());navigator.serviceWorker.ready.then(()=>refreshOfflineStatus()).catch(()=>{});registration.update().catch(()=>{});await refreshOfflineStatus();}
 catch{$('shell-status').textContent='离线页面未准备好，请联网重试';}
}

function attachEvents(){
 document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>showView(el.dataset.view)));
 $('return-chat')?.addEventListener('click',()=>showView('chat'));
 document.querySelectorAll('.close-dialog').forEach(el=>el.addEventListener('click',()=>el.closest('dialog').close()));$('review-dialog').addEventListener('close',()=>{review=null;clearOCRText();});$('import-dialog').addEventListener('close',()=>importBatch=null);document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('close',()=>setTimeout(drainCaptures,0)));window.addEventListener('hashchange',()=>consumeCapture(location.hash));
 $('manual-entry').addEventListener('click',()=>openReview([normalizeRecord({source:'manual',status:'pending',amountCents:null,merchant:'',category:'其他'})]));$('ledger-add').addEventListener('click',()=>showView('capture'));
 $('parse-sentence').addEventListener('click',()=>parseSentence().catch(e=>showToast(friendlyError(e))));$('sentence').addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();parseSentence().catch(e=>showToast(friendlyError(e)));}});
 $('focus-sentence')?.addEventListener('click',()=>{showView('capture');setSentencePanel(true);const details=$('sentence').closest('details');if(details)details.open=true;$('sentence').focus({preventScroll:true});$('sentence').scrollIntoView({block:'center',behavior:'instant'});});
 $('close-sentence')?.addEventListener('click',()=>{setSentencePanel(false);$('focus-sentence')?.focus({preventScroll:true});});$('sentence').addEventListener('input',updateSentenceActionNote);updateSentenceActionNote();
 $('pick-screenshot').addEventListener('click',()=>canUse()&&$('screenshot-file').click());$('screenshot-file').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';readScreenshot(file);});$('cancel-ocr').addEventListener('click',()=>ocrAbort?.abort());
 $('pick-import').addEventListener('click',()=>canUse()&&$('bill-file').click());$('bill-file').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';readImport(file);});$('commit-import').addEventListener('click',commitImport);
 $('review-form').addEventListener('submit',saveReviewed);$('reparse-ocr').addEventListener('click',reparseOCRText);$('draft-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-draft-index]');if(!button||!review)return;rememberCurrentDraft();review.index=Number(button.dataset.draftIndex);drawReview();});
 $('review-form').addEventListener('invalid',event=>{const details=event.target.closest('details');if(details)details.open=true;},true);
 for(const id of['review-amount','review-channel'])$(id).addEventListener('input',updateDuplicateNotice);for(const id of['review-merchant','review-date','review-type','review-category','review-purpose'])$(id).addEventListener('input',updateReviewSuggestions);
 $('delete-record').addEventListener('click',async()=>{if(!review?.existingId)return;const record=state.records.find(r=>r.id===review.existingId),revision=state.revision;if(!record)return;if(!await ask('删除这笔记录',`${record.merchant} · ${formatMoney(record.amountCents)}。删除后可在本次页面中撤销。`,'确认删除'))return;if(state.revision!==revision){showToast('账本在确认期间有变化，本次删除已取消，请重新查看。');return;}try{await commit(next=>{next.records=next.records.filter(r=>r.id!==record.id);},{kind:'delete',before:clone(record),ids:[record.id],description:'刚才删除的一笔'});closeReview();showToast('这笔已删除',true);}catch(error){showToast(friendlyError(error));}});
 document.addEventListener('click',event=>{const row=event.target.closest('[data-record]');if(row&&state){const record=state.records.find(r=>r.id===row.dataset.record);if(record)openReview([record],record.id);}});
 for(const id of['ledger-search','ledger-month'])$(id).addEventListener('input',()=>{ledgerLimit=100;if(id==='ledger-month'){ledgerStatsCategory='';showAllMonths=false;$('all-months').setAttribute('aria-pressed','false');}renderLedger();});$('all-months').addEventListener('click',()=>{ledgerStatsCategory='';showAllMonths=!showAllMonths;ledgerLimit=100;$('all-months').setAttribute('aria-pressed',String(showAllMonths));renderLedger();});
 $('ledger-category-filter')?.addEventListener('click',()=>{ledgerStatsCategory='';ledgerLimit=100;renderLedger();});
 document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{ledgerStatsCategory='';setLedgerTypeFilter(button.dataset.filter);ledgerLimit=100;renderLedger();}));$('load-more').addEventListener('click',()=>{ledgerLimit+=100;renderLedger();});
 $('category-chart').addEventListener('click',event=>{const button=event.target.closest('[data-stats-category]');if(button)openStatsCategory(button.dataset.statsCategory);});
 $('stats-month').addEventListener('input',renderStats);$('edit-budget').addEventListener('click',()=>{$('budget-amount').value=state.budgets[$('stats-month').value]?String(state.budgets[$('stats-month').value]/100):'';$('budget-error').hidden=true;$('budget-dialog').showModal();});$('budget-form').addEventListener('submit',async event=>{event.preventDefault();const amount=$('budget-amount').value.trim()?parseMoney($('budget-amount').value):null;if($('budget-amount').value.trim()&&(!amount||amount<0||amount>MAX_CENTS)){$('budget-error').textContent='请输入大于 0、最多两位小数且不超过 999,999,999.99 元的预算。';$('budget-error').hidden=false;return;}try{await commit(next=>{if(amount===null)delete next.budgets[$('stats-month').value];else next.budgets[$('stats-month').value]=amount;});$('budget-dialog').close();showToast('预算已保存');}catch(error){showToast(friendlyError(error));}});
 $('export-backup').addEventListener('click',backup);$('backup-nudge').addEventListener('click',()=>showView('settings'));$('import-backup').addEventListener('click',()=>$('backup-file').click());$('backup-file').addEventListener('change',event=>{const file=event.target.files?.[0];event.target.value='';restore(file);});$('export-csv').addEventListener('click',()=>{if(!state)return;downloadFile(`轻记流水-${showAllMonths?'全部':$('ledger-month').value}.csv`,exportCSV(filteredRecords()),'text/csv;charset=utf-8');showToast('已发起当前筛选流水的 CSV 下载');});
 $('rules-list').addEventListener('click',async event=>{const button=event.target.closest('[data-remove-rule]');if(!button)return;try{await commit(next=>delete next.rules[button.dataset.removeRule]);showToast('已忘记这家商户的分类');}catch(error){showToast(friendlyError(error));}});
 $('import-table-wrap').addEventListener('change',event=>{if(!importBatch)return;if(event.target.id==='import-select-all'){importBatch.entries.forEach(entry=>entry.selected=event.target.checked);drawImport();}else if(event.target.dataset.importIndex!==undefined){importBatch.entries[Number(event.target.dataset.importIndex)].selected=event.target.checked;event.target.closest('tr').classList.toggle('unselected',!event.target.checked);importSummary();}});$('import-table-wrap').addEventListener('click',event=>{if(event.target.id==='import-show-more'&&importBatch){importBatch.limit+=200;drawImport();}});
 $('toast-close').addEventListener('click',hideToast);
 $('toast').addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'){toastPointerOver=true;pauseToast();}});
 $('toast').addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'){toastPointerOver=false;resumeToast();}});
 $('toast').addEventListener('focusin',pauseToast);
 $('toast').addEventListener('focusout',event=>{if(!$('toast').contains(event.relatedTarget))queueMicrotask(resumeToast);});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)hideToast();});window.addEventListener('pagehide',hideToast);
 $('undo-action').addEventListener('click',undoLast);$('prepare-offline').addEventListener('click',prepareOffline);$('apply-update').addEventListener('click',applyProgramUpdate);$('check-update').addEventListener('click',checkAppUpdate);document.querySelectorAll('[data-update-entry]').forEach(link=>link.addEventListener('click',event=>{if(unfinishedWork()){event.preventDefault();showToast('请先保存或取消当前草稿，再打开更新入口。');}}));
 $('request-persistence').addEventListener('click',async()=>{if(!navigator.storage?.persist){showToast('当前浏览器不支持保留请求，请定期导出备份。');return;}const retained=await navigator.storage.persist().catch(()=>false);showToast(retained?'浏览器已同意尽量保留；仍建议定期备份。':'浏览器暂未同意长期保留，请用备份保护账目。');});
 $('copy-bridge').addEventListener('click',async()=>{if(!canUse())return;const base=new URL('./',location.href);const prefix=`${base.href}#ledger=${encodeURIComponent(state.ledgerId)}&source=${encodeURIComponent(state.sourceToken)}&capture=`;try{await navigator.clipboard.writeText(prefix);showToast('入口已复制，请仅放进你自己的快捷指令。');}catch{showToast('复制未成功，请用 Safari 普通网页并允许剪贴板写入。');}});
 $('reset-bridge').addEventListener('click',async()=>{if(!canUse()||!await ask('重置截图来源标记','旧的截图入口会失效。重置后请重新复制当前入口，并更新自己的快捷指令。','重置标记'))return;try{await commit(next=>{next.sourceToken=randomToken();});captureQueue.length=0;showToast('旧入口已失效，请重新复制当前账本入口。');}catch(error){showToast(friendlyError(error));}});
 const connectivity=()=>{$('connection-label').textContent=navigator.onLine?'本机账本':'离线 · 本机账本';};window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);connectivity();
 if(channel)channel.onmessage=async()=>{if(!busy&&state){const fresh=await db.read();if(fresh&&fresh.revision>state.revision){state=fresh;lastAction=null;renderAll();showToast('已更新为其他页面保存的账本。');}}};
}
function consumeCapture(hash){const params=new URLSearchParams(hash.replace(/^#/,''));if(!params.has('capture'))return;history.replaceState(null,'',location.pathname+location.search);if(!state){showReply('账本尚未打开，这次没有记账。请稍后重新选图。');return;}const incoming=readCapture(hash,state);if(incoming?.error){showReply(incoming.error);return;}const parsed=parseReceipt(incoming.text,{rules:state.rules});if(!parsed.drafts.length){showReply(parsed.reason||'没有找到可记账的交易信息。');return;}if(document.querySelector('dialog[open]')){if(captureQueue.length>=5){showToast('待核对截图已满，本次没有记账，请处理后重选。');return;}captureQueue.push(parsed.drafts);showToast('又收到一张截图，处理完当前内容后继续核对。');}else{showView('capture');openReview(parsed.drafts);}}
function drainCaptures(){if(captureQueue.length&&!document.querySelector('dialog[open]')){showView('capture');openReview(captureQueue.shift());}}
async function start(){
 aiAssistant=createAIAssistant({getContext:reviewAIContext,onApply:(field,value)=>{if(!review)return;const id={merchant:'review-merchant',category:'review-category',purpose:'review-purpose'}[field];if(!id)return;$(id).value=value;$(id).dispatchEvent(new Event('input',{bubbles:true}));}});
  chatUI=createChatUI({host:$('view-chat'),getService:()=>aiAssistant.getSessionInfo(),setSessionKey:key=>aiAssistant.setSessionKey(key),onConfigure:configureChatService,request:args=>aiAssistant.requestChat(args),onSave:saveChatDraft,onEdit:editChatDraft,onUndo:undoLast,getUndoableId:()=>lastAction?.ids?.length===1?lastAction.ids[0]:null,getToday:()=>localDate(),getRecord:id=>{const record=state?.records.find(item=>item.id===id);return record?clone(record):null;}});
 $('app-version').textContent='版本 '+APP_VERSION_LABEL;renderIcons();renderStickers();$('review-category').innerHTML=CATEGORIES.map(category=>`<option>${category}</option>`).join('');$('today-label').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('ledger-month').value=thisMonth;$('stats-month').value=thisMonth;attachEvents();
 const incomingHash=location.hash;if(new URLSearchParams(incomingHash.replace(/^#/,'' )).has('capture'))history.replaceState(null,'',location.pathname+location.search);
 try{state=await db.open();renderAll();consumeCapture(incomingHash);}
 catch(error){$('storage-warning').textContent='本机账本暂时无法打开：'+friendlyError(error)+'。这时不会显示保存成功，也不会在内存里假装记账。';$('storage-warning').hidden=false;document.querySelectorAll('#parse-sentence,#manual-entry,#pick-import,#pick-screenshot,#export-backup,#import-backup').forEach(el=>el.disabled=true);}
 setupServiceWorker();
}
start().catch(error=>{$('storage-warning').textContent='页面启动未完成：'+friendlyError(error);$('storage-warning').hidden=false;});
